@dataclass
class Erp:
    root: Path
    launch_at: datetime
    pos: list[dict] = field(default_factory=list)
    grs: list[dict] = field(default_factory=list)
    stock: list[dict] = field(default_factory=list)
    bom: list[dict] = field(default_factory=list)
